const recurringTemplateRows = `-- name: RecurringTemplateRows :many
WITH children AS MATERIALIZED (
  SELECT business_id, billing_cycle_ref->>'template_invoice_id' AS template_id, issue_date, billing_cycle_ref,
         count(*) OVER (PARTITION BY billing_cycle_ref->>'template_invoice_id') AS generated_count,
         row_number() OVER (PARTITION BY billing_cycle_ref->>'template_invoice_id' ORDER BY issue_date DESC NULLS LAST) AS position
  FROM invoices
  WHERE business_id=$1::uuid AND NOT is_template AND invoice_type = 'RECURRING' AND status <> 'VOID'
)
SELECT t.invoice_id, t.customer_id, c.name AS customer_name, t.currency, t.amount,
       t.payment_terms, t.billing_cycle_ref, t.created_at,
       COALESCE(ch.generated_count, 0)::bigint AS generated_count,
       ch.issue_date AS previous_issue_date, ch.billing_cycle_ref AS previous_ref
FROM invoices t
LEFT JOIN customers c ON c.customer_id = t.customer_id AND c.business_id=t.business_id
LEFT JOIN children ch ON ch.business_id = t.business_id AND ch.template_id = t.invoice_id::text AND ch.position = 1
WHERE t.business_id=$1::uuid AND t.is_template ORDER BY t.created_at DESC
`

type RecurringTemplateRowsRow struct {
	InvoiceID         pgtype.UUID
	CustomerID        pgtype.UUID
	CustomerName      pgtype.Text
	Currency          string
	Amount            pgtype.Numeric
	PaymentTerms      pgtype.Text
	BillingCycleRef   []byte
	CreatedAt         pgtype.Timestamp
	GeneratedCount    int64
	PreviousIssueDate pgtype.Date
	PreviousRef       []byte
}

func (q *Queries) RecurringTemplateRows(ctx context.Context, businessID pgtype.UUID) ([]RecurringTemplateRowsRow, error) {
	rows, err := q.db.Query(ctx, recurringTemplateRows, businessID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []RecurringTemplateRowsRow
	for rows.Next() {
		var i RecurringTemplateRowsRow
		if err := rows.Scan(
			&i.InvoiceID,
			&i.CustomerID,
			&i.CustomerName,
			&i.Currency,
			&i.Amount,
			&i.PaymentTerms,
			&i.BillingCycleRef,
			&i.CreatedAt,
			&i.GeneratedCount,
			&i.PreviousIssueDate,
			&i.PreviousRef,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

